CREATE TABLE secrets (
	account_id TEXT NOT NULL REFERENCES accounts (account_id) ON DELETE CASCADE,
	secret_id TEXT NOT NULL,
	sealed BLOB NOT NULL, -- AES-256-GCM under the key in secrets.key; compared by decrypting, never by a stored hash
	created_at INTEGER NOT NULL,
	PRIMARY KEY (account_id, secret_id)
) STRICT;
CREATE TABLE listening_sessions (
	account_id TEXT NOT NULL REFERENCES accounts (account_id) ON DELETE CASCADE,
	session_id TEXT NOT NULL,
	scope TEXT NOT NULL,     -- the episode scope of its start
	author_id TEXT NOT NULL, -- the only author who may append to or finalize it
	start_node TEXT NOT NULL,
	sealed_by TEXT,          -- its end
	finalized_by TEXT,       -- its finalization
	PRIMARY KEY (account_id, session_id)
) STRICT;
INSERT INTO listening_sessions VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000004','episode:g1:8bc6d52c55ffe3b58d6ef033c61068631136e5446828022f3cf61eb692581d7f:e1:2251be81f2e26cc1fa0c8ce393cad1ebd155dcf381e80c27e2439e3aa3dfc6e5','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000005',NULL,NULL);
CREATE TABLE session_facts (
	account_id TEXT NOT NULL,
	session_id TEXT NOT NULL,
	ordinal INTEGER NOT NULL,
	node_id TEXT NOT NULL,
	PRIMARY KEY (account_id, session_id, ordinal),
	FOREIGN KEY (account_id, session_id) REFERENCES listening_sessions (account_id, session_id) ON DELETE CASCADE
) STRICT;
INSERT INTO session_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000004',0,'00000000-0000-4000-8000-000000000005');
INSERT INTO session_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000004',1,'00000000-0000-4000-8000-000000000006');
INSERT INTO session_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000004',2,'00000000-0000-4000-8000-000000000008');
CREATE TABLE listening_facts (
	account_id TEXT NOT NULL,
	node_id TEXT NOT NULL,
	scope TEXT NOT NULL,
	history_entry INTEGER NOT NULL CHECK (history_entry IN (0, 1)),
	session_id TEXT,  -- with ordinal: a session fact a statistics reset can cut
	ordinal INTEGER,
	removal INTEGER NOT NULL CHECK (removal IN (0, 1)),
	restores TEXT,    -- for a history restore: the removal it cancels
	PRIMARY KEY (account_id, node_id),
	FOREIGN KEY (account_id, node_id) REFERENCES causal_nodes (account_id, node_id) ON DELETE CASCADE
) STRICT;
INSERT INTO listening_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000005','episode:g1:8bc6d52c55ffe3b58d6ef033c61068631136e5446828022f3cf61eb692581d7f:e1:2251be81f2e26cc1fa0c8ce393cad1ebd155dcf381e80c27e2439e3aa3dfc6e5',1,'00000000-0000-4000-8000-000000000004',0,0,NULL);
INSERT INTO listening_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000006','episode:g1:8bc6d52c55ffe3b58d6ef033c61068631136e5446828022f3cf61eb692581d7f:e1:2251be81f2e26cc1fa0c8ce393cad1ebd155dcf381e80c27e2439e3aa3dfc6e5',1,'00000000-0000-4000-8000-000000000004',1,0,NULL);
INSERT INTO listening_facts VALUES('ae9b8a2e-26f0-4bc0-8729-e42eccebf157','00000000-0000-4000-8000-000000000008','episode:g1:8bc6d52c55ffe3b58d6ef033c61068631136e5446828022f3cf61eb692581d7f:e1:2251be81f2e26cc1fa0c8ce393cad1ebd155dcf381e80c27e2439e3aa3dfc6e5',1,'00000000-0000-4000-8000-000000000004',2,0,NULL);
CREATE TABLE queue_entries (
	account_id TEXT NOT NULL REFERENCES accounts (account_id) ON DELETE CASCADE,
	episode_id TEXT NOT NULL,
	generation_id TEXT NOT NULL,
	queue_key TEXT NOT NULL,    -- contract-v1 key "q1:<n>:<m>"
	position_id TEXT NOT NULL,  -- a UUID
	membership_by TEXT NOT NULL, -- the nodes that determine membership and position
	position_by TEXT NOT NULL,
	PRIMARY KEY (account_id, episode_id)
) STRICT;
CREATE TABLE queue_frontier (
	account_id TEXT NOT NULL,
	node_id TEXT NOT NULL,
	PRIMARY KEY (account_id, node_id),
	FOREIGN KEY (account_id, node_id) REFERENCES causal_nodes (account_id, node_id) ON DELETE CASCADE
) STRICT;
CREATE INDEX auth_tokens_installation ON auth_tokens (account_id, install_id);
CREATE INDEX facts_rejected ON facts (account_id, epoch, seq, op_id) WHERE outcome = 'rejected';
CREATE INDEX decisions_subject ON decisions (account_id, decision_type, subject, epoch, seq, decision_id);
CREATE INDEX transport_slots_by_seq ON transport_slots (account_id, install_id, seq);
CREATE UNIQUE INDEX node_order_rank ON node_order (account_id, rank);
CREATE INDEX generations_by_podcast ON generations (account_id, podcast_id);
CREATE INDEX listening_facts_by_scope ON listening_facts (account_id, scope);
CREATE UNIQUE INDEX listening_facts_restores ON listening_facts (account_id, restores) WHERE restores IS NOT NULL;
COMMIT;
